import{_ as n,o as e,c as i,a5 as h}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"System Health: chuyển persistence từ PostgreSQL sang MongoDB","description":"","frontmatter":{},"headers":[],"relativePath":"feature/system-health-mongodb-refactor/spec.md","filePath":"feature/system-health-mongodb-refactor/spec.md"}'),o={name:"feature/system-health-mongodb-refactor/spec.md"};function r(a,t,c,s,g,l){return e(),i("div",null,[...t[0]||(t[0]=[h('<h1 id="system-health-chuyen-persistence-tu-postgresql-sang-mongodb" tabindex="-1">System Health: chuyển persistence từ PostgreSQL sang MongoDB <a class="header-anchor" href="#system-health-chuyen-persistence-tu-postgresql-sang-mongodb" aria-label="Permalink to &quot;System Health: chuyển persistence từ PostgreSQL sang MongoDB&quot;">​</a></h1><p>Ngày: 2026-10-22. Trạng thái: đang triển khai.</p><h2 id="muc-tieu-va-phan-bien" tabindex="-1">Mục tiêu và phản biện <a class="header-anchor" href="#muc-tieu-va-phan-bien" aria-label="Permalink to &quot;Mục tiêu và phản biện&quot;">​</a></h2><p>Chuyển toàn bộ persistence thuộc FR 3.10.3 sang MongoDB để tách nhịp ghi monitoring khỏi PostgreSQL. Giữ nguyên giao diện, API và hành vi nghiệp vụ hiện có.</p><p>Số bảng không phải thước đo tải. File init PostgreSQL hiện có <strong>95 câu CREATE TABLE</strong>, không chứng minh database đang chạy có 95 bảng hoặc đang quá tải. System Health chiếm 5 bảng, chỉ giữ mẫu mới nhất; chuyển xong chỉ giảm 5 bảng sau bước dọn dẹp. Cần đo trước/sau để xác nhận lợi ích, không hứa tăng hiệu năng khi chưa benchmark.</p><p>Worker Node gửi heartbeat host và collector mỗi 15 giây, probe mặc định 30 giây sau lần hoàn tất. Ước lượng nhịp ghi đầu vào: <code>servers/15 + collectors/15 + tổng(1/chu kỳ probe thực tế)</code> mỗi giây, chưa tính enrollment/provisioning. PostgreSQL vẫn phục vụ xác thực ADMIN và các nghiệp vụ khác.</p><h2 id="pham-vi" tabindex="-1">Phạm vi <a class="header-anchor" href="#pham-vi" aria-label="Permalink to &quot;Phạm vi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>PostgreSQL hiện tại</th><th>Đích MongoDB</th></tr></thead><tbody><tr><td>monitoring_servers</td><td>monitoring_servers</td></tr><tr><td>monitoring_collectors</td><td>monitoring_collectors</td></tr><tr><td>monitoring_health_targets</td><td>monitoring_health_targets</td></tr><tr><td>monitoring_health_results</td><td>latestResult trong monitoring_health_targets</td></tr><tr><td>monitoring_enrollments</td><td>monitoring_enrollments</td></tr></tbody></table><p>Không chuyển user/role, subscription, billing, audit khác; không chuyển toàn bộ 80+ bảng; không thêm lịch sử metrics, time-series, Prometheus hay service mới. PostgreSQL probe vẫn được giữ: database được kiểm tra khác với nơi lưu monitoring.</p><h2 id="user-stories" tabindex="-1">User stories <a class="header-anchor" href="#user-stories" aria-label="Permalink to &quot;User stories&quot;">​</a></h2><ol><li>ADMIN xem host, service và dependency với cùng dữ liệu, bộ lọc, phân trang và trạng thái như trước.</li><li>Agent/collector tiếp tục gửi request với UUID và token đang dùng, không phải cài lại.</li><li>Operator provision catalog bằng công cụ hiện có đã đổi persistence, giữ mẫu và metadata đúng quyền sở hữu.</li><li>ADMIN tạo lời mời cài host dùng đúng một lần, hết hạn sau 900 giây.</li><li>Operator có thể chuyển đổi, đối soát và quay lại PostgreSQL bằng runbook có kiểm chứng.</li></ol><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Các đường dẫn <code>/api/monitoring/servers</code>, <code>/heartbeat</code>, <code>/collectors/heartbeat</code>, <code>/health-targets</code>, <code>/health-results</code>, <code>/enrollments</code>, <code>/register</code>, <code>/install.sh</code>, <code>/agent.py</code> giữ request/response contract, envelope, lỗi nghiệp vụ, UUID và nullability.</li><li>Current ADMIN vẫn được kiểm tra lại qua UserSystemRoleRepository; thu hồi quyền có hiệu lực ở lần đọc tiếp theo. Không sao chép role sang Mongo để né truy vấn này.</li><li>Host chưa có mẫu là NO_DATA; đúng 60 giây vẫn ONLINE, sau đó OFFLINE. Collector quá 60 giây không làm mọi service thành DOWN: kết quả hiển thị UNKNOWN/COLLECTOR_OFFLINE.</li><li>Probe quá staleAfterSeconds là UNKNOWN/STALE; vẫn giữ lastKnownStatus. Không TTL xóa host, collector, target hoặc latestResult.</li><li>Lặp current checkId là duplicate, không đổi receivedAt. Check khác có checkedAt cũ hoặc bằng bị 409. Giữ thứ tự kiểm tra quyền → duplicate/order → validation như hiện tại.</li><li>Receipt time do backend gán. Cho phép future skew tối đa 10 giây; không nhận mẫu quá cũ. Giữ validation reason/outcome/HTTP/runtime, metrics null và khoảng giá trị.</li><li>Không tự tạo target/host từ heartbeat hoặc probe. Target phải thuộc collector; reassign phải xóa kết quả cũ cùng lần cập nhật.</li><li>Enrollment hết hạn không thể dùng dù document chưa được TTL dọn; hai request đồng thời chỉ tạo một host. Insert host thất bại không làm mất lời mời.</li><li>Provisioning giữ tính nguyên tử cả batch như công cụ SQL hiện tại; không ghi đè mẫu bằng dữ liệu config cũ. Không cho orphan reference hoặc xóa đối tượng đang được tham chiếu.</li><li>Sau cutover, ghi monitoring và provisioning không dùng 5 bảng SQL. Đọc ADMIN có thể vẫn dùng PostgreSQL theo thiết kế.</li><li>Khi Mongo lỗi, trả lỗi nguồn dữ liệu, không giả lập trạng thái healthy/down và không fallback từng request sang SQL.</li><li>Không thay UX/i18n/theme. Kiểm tra lại hai ngôn ngữ và hai theme trên màn hiện có; nếu phát sinh text UI mới phải bổ sung key vi/en trước triển khai.</li></ul><h2 id="quyet-đinh-va-gia-đinh" tabindex="-1">Quyết định và giả định <a class="header-anchor" href="#quyet-đinh-va-gia-đinh" aria-label="Permalink to &quot;Quyết định và giả định&quot;">​</a></h2><p>Chọn một cửa sổ bảo trì ngắn, tạm dừng writers để chuyển nhất quán; không dual-write. Dữ liệu latest nhỏ nên đây là phương án ít rủi ro vận hành hơn, nhưng phải đo thời gian rehearsal. Ngân sách tạm dừng đề xuất ≤10 phút; nếu không đạt, thiết kế lại cutover trước thực hiện.</p><p>Mongo production/test phải hỗ trợ multi-document transaction. Cấu hình hỗ trợ storage mode <code>monitoring.storage=postgres|mongo</code> (mặc định postgres, bật mongo khi cutover).</p><h2 id="nguon-nghien-cuu-goc" tabindex="-1">Nguồn nghiên cứu gốc <a class="header-anchor" href="#nguon-nghien-cuu-goc" aria-label="Permalink to &quot;Nguồn nghiên cứu gốc&quot;">​</a></h2><ul><li><a href="./../../../../tuan-research/system-health-mongodb-refactor/spec.html">Tuan Research: system-health-mongodb-refactor</a></li></ul>',18)])])}const m=n(o,[["render",r]]);export{d as __pageData,m as default};
